import * as path from 'path';
import { stringify } from 'yaml';

export const DOCS_DIR = path.resolve(__dirname, '..', '..', 'docs');
export const OPENAPI_PATH = path.join(DOCS_DIR, 'backend-openapi.yaml');
export const ASYNCAPI_PATH = path.join(DOCS_DIR, 'websockets-asyncapi-draft.yaml');

const HEADER =
  '# GENERATED by `npm run spec:generate` in server/ -- do not edit by hand.\n' +
  '# `npm run spec:check` fails CI when this file is out of date.\n';

/** Deterministic YAML: no line folding, so a long description diffs as one line. */
export function renderYaml(document: unknown): string {
  return HEADER + stringify(document, { lineWidth: 0, aliasDuplicateObjects: false });
}
